#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;
    vector<long long> par(n);
    for (int i = 0; i < n; i++) cin >> par[i];

    vector<vector<int>> kids(n + 1);
    int root = 0;
    for (int v = 1; v <= n; v++) {
        if (par[v - 1] == 0) root = v;
        else kids[par[v - 1]].push_back(v);
    }
    vector<int> order = {root};
    for (size_t i = 0; i < order.size(); i++) {
        for (int c : kids[order[i]]) order.push_back(c);
    }
    vector<long long> sizes(n + 1, 1);
    for (size_t i = order.size(); i-- > 0;) {
        int v = order[i];
        if (par[v - 1] != 0) sizes[par[v - 1]] += sizes[v];
    }
    for (int v = 1; v <= n; v++) cout << (v > 1 ? " " : "") << sizes[v];
    cout << "\n";

    return 0;
}

